# Apply boosts for phrase fields, bigram fields, and trigram fields
if pf:
    scores = apply_pf_boosts(scores, pf, frame, query_fields)
if pf2:
    scores = apply_pf2_boosts(scores, pf2, frame, query_fields)
if pf3:
    scores = apply_pf3_boosts(scores, pf3, frame, query_fields)

return scores, explanation
